const products = {
  lamp: { slug: 'lamp', name: 'Brass lamp', usd: 120 },
  vase: { slug: 'vase', name: 'Stone vase', usd: 80 },
}

export async function getProduct(slug: string, currency: string) {
  await new Promise((resolve) => setTimeout(resolve, 120))
  const product = products[slug as keyof typeof products]
  if (!product) return null
  const rate = currency === 'EUR' ? 0.92 : 1
  return { ...product, price: `${currency} ${(product.usd * rate).toFixed(2)}` }
}

export async function getRelatedProducts(slug: string) {
  await new Promise((resolve) => setTimeout(resolve, 420))
  return Object.values(products).filter((product) => product.slug !== slug)
}
import Link from 'next/link'
import type { ReactNode } from 'react'

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>
        <nav>
          <Link href="/">Signal Shop</Link>
        </nav>
        {children}
      </body>
    </html>
  )
}
import Link from 'next/link'

export default function HomePage() {
  return (
    <main>
      <h1>Signal Shop</h1>
      <Link href="/products/lamp?currency=EUR">Brass lamp</Link>
    </main>
  )
}
import { notFound } from 'next/navigation'
import { getProduct, getRelatedProducts } from '@/lib/products'

export default async function ProductPage({
  params,
  searchParams,
}: {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ currency?: string }>
}) {
  const { slug } = await params
  const { currency = 'USD' } = await searchParams
  const product = await getProduct(slug, currency)
  if (!product) notFound()
  const related = await getRelatedProducts(slug)

  return (
    <main>
      <p>Signal Shop collection</p>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
